def transform(grid):
    h, w = len(grid), len(grid[0])
    template = [[int(grid[r][c] == 0) for c in range(w)] for r in range(h)]
    out = [[0 for _ in range(3*w)] for _ in range(3*h)]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 0:
                for dr in range(h):
                    for dc in range(w):
                        if template[dr][dc]:
                            out[3*r+dr][3*c+dc] = value
    return out

